-- SAMPLE CONTENT for testing. Every row is marked is_sample = true and shows on the
-- site as a glowing placeholder. Run after 0001_admin.sql (SQL Editor, paste, Run).
-- Running it again does nothing if the samples are already there.

insert into public.listings (slug, type, status, featured, sort, title_en, title_ta, location_en, location_ta, price_en, price_ta, size_en, size_ta, description_en, description_ta, features_en, features_ta, is_sample) values
  ('sample-plot-1', 'plot', 'published', true, 0, 'Residential plot near main road', 'பிரதான சாலை அருகே குடியிருப்பு மனை', 'Coimbatore', 'கோயம்புத்தூர்', '₹ [00,00,000]', '₹ [00,00,000]', '[1,200] sq ft', '[1,200] சதுர அடி', 'Sample description. The client adds the real details, approvals and photos from the admin page.', 'மாதிரி விளக்கம். உண்மையான விவரங்கள், அனுமதிகள் மற்றும் படங்களை வாடிக்கையாளர் அட்மின் பக்கத்தில் சேர்ப்பார்.', array['Clear title (to verify)', 'Road access', 'Water and power nearby']::text[], array['தெளிவான பட்டா (சரிபார்க்க)', 'சாலை வசதி', 'அருகில் தண்ணீர் மற்றும் மின்சாரம்']::text[], true),
  ('sample-house-1', 'house', 'published', true, 1, '2 BHK independent house', '2 BHK தனி வீடு', 'Madurai', 'மதுரை', '₹ [00,00,000]', '₹ [00,00,000]', '[1,100] sq ft', '[1,100] சதுர அடி', 'Sample description. The client adds the real details, approvals and photos from the admin page.', 'மாதிரி விளக்கம். உண்மையான விவரங்கள், அனுமதிகள் மற்றும் படங்களை வாடிக்கையாளர் அட்மின் பக்கத்தில் சேர்ப்பார்.', array['2 bedrooms', 'Car parking', 'Close to schools']::text[], array['2 படுக்கையறைகள்', 'கார் நிறுத்தம்', 'பள்ளிகள் அருகில்']::text[], true),
  ('sample-apartment-1', 'apartment', 'published', true, 2, '3 BHK apartment with lift', 'லிஃப்ட் வசதியுடன் 3 BHK அடுக்குமாடி', 'Chennai', 'சென்னை', '₹ [00,00,000]', '₹ [00,00,000]', '[1,450] sq ft', '[1,450] சதுர அடி', 'Sample description. The client adds the real details, approvals and photos from the admin page.', 'மாதிரி விளக்கம். உண்மையான விவரங்கள், அனுமதிகள் மற்றும் படங்களை வாடிக்கையாளர் அட்மின் பக்கத்தில் சேர்ப்பார்.', array['3 bedrooms', 'Lift and power backup', 'Covered parking']::text[], array['3 படுக்கையறைகள்', 'லிஃப்ட் மற்றும் மின் காப்பு', 'மூடிய வாகன நிறுத்தம்']::text[], true),
  ('sample-commercial-1', 'commercial', 'published', false, 3, 'Ground floor shop space', 'தரை தள கடை இடம்', 'Chennai', 'சென்னை', '₹ [00,00,000]', '₹ [00,00,000]', '[600] sq ft', '[600] சதுர அடி', 'Sample description. The client adds the real details, approvals and photos from the admin page.', 'மாதிரி விளக்கம். உண்மையான விவரங்கள், அனுமதிகள் மற்றும் படங்களை வாடிக்கையாளர் அட்மின் பக்கத்தில் சேர்ப்பார்.', array['Main road frontage', 'Suitable for retail', 'Shared parking']::text[], array['பிரதான சாலை முகப்பு', 'சில்லறை வணிகத்திற்கு ஏற்றது', 'பொது வாகன நிறுத்தம்']::text[], true),
  ('sample-plot-2', 'plot', 'published', false, 4, 'Corner plot in a gated layout', 'கேட்டட் லேஅவுட்டில் மூலை மனை', 'Madurai', 'மதுரை', '₹ [00,00,000]', '₹ [00,00,000]', '[2,400] sq ft', '[2,400] சதுர அடி', 'Sample description. The client adds the real details, approvals and photos from the admin page.', 'மாதிரி விளக்கம். உண்மையான விவரங்கள், அனுமதிகள் மற்றும் படங்களை வாடிக்கையாளர் அட்மின் பக்கத்தில் சேர்ப்பார்.', array['Corner plot', 'Gated layout', 'Approval to verify']::text[], array['மூலை மனை', 'கேட்டட் லேஅவுட்', 'அனுமதி சரிபார்க்க']::text[], true),
  ('sample-house-2', 'house', 'published', false, 5, '3 BHK villa with garden', 'தோட்டத்துடன் 3 BHK வில்லா', 'Coimbatore', 'கோயம்புத்தூர்', '₹ [00,00,000]', '₹ [00,00,000]', '[1,800] sq ft', '[1,800] சதுர அடி', 'Sample description. The client adds the real details, approvals and photos from the admin page.', 'மாதிரி விளக்கம். உண்மையான விவரங்கள், அனுமதிகள் மற்றும் படங்களை வாடிக்கையாளர் அட்மின் பக்கத்தில் சேர்ப்பார்.', array['3 bedrooms', 'Garden', 'Quiet street']::text[], array['3 படுக்கையறைகள்', 'தோட்டம்', 'அமைதியான தெரு']::text[], true)
on conflict (slug) do nothing;

insert into public.faqs (category, question_en, question_ta, answer_en, answer_ta, sort, published, show_on_home, is_sample)
select * from (values
  ('general', 'Do you charge a fee for advice?', 'ஆலோசனைக்கு கட்டணம் உண்டா?', 'Draft answer for the client to confirm.', 'வாடிக்கையாளர் உறுதி செய்ய வேண்டிய வரைவு பதில்.', 0, true, false, true),
  ('general', 'Which areas do you serve?', 'எந்த பகுதிகளில் சேவை செய்கிறீர்கள்?', 'I am based in Tamil Nadu and help clients across India. Exact areas to be confirmed.', 'நான் தமிழ்நாட்டில் இருக்கிறேன், இந்தியா முழுவதும் வாடிக்கையாளர்களுக்கு உதவுகிறேன். சரியான பகுதிகள் உறுதி செய்யப்படும்.', 1, true, false, true),
  ('general', 'Can we talk in Tamil?', 'தமிழில் பேசலாமா?', 'Yes. You can call, WhatsApp or chat in Tamil or English.', 'ஆம். தமிழ் அல்லது ஆங்கிலத்தில் அழைக்கலாம், வாட்ஸ்அப் செய்யலாம் அல்லது அரட்டை செய்யலாம்.', 2, true, false, true),
  ('health', 'Which health plan is right for my family?', 'என் குடும்பத்திற்கு எந்த ஆரோக்கிய திட்டம் சரி?', 'It depends on ages, health and budget. Share your family details and I will explain suitable options.', 'வயது, ஆரோக்கியம் மற்றும் பட்ஜெட்டைப் பொறுத்தது. குடும்ப விவரங்களை சொல்லுங்கள், பொருத்தமான வாய்ப்புகளை விளக்குகிறேன்.', 0, true, true, true),
  ('health', 'How do I make a cashless claim?', 'பணமில்லா கிளைம் செய்வது எப்படி?', 'At a network hospital, show your health card at the insurance desk. I can guide you through the steps.', 'நெட்வொர்க் மருத்துவமனையில் காப்பீட்டு மேசையில் உங்கள் ஹெல்த் கார்டை காட்டுங்கள். படிகளில் நான் வழிகாட்டுகிறேன்.', 1, true, true, true),
  ('life', 'What is the difference between term and savings plans?', 'டெர்ம் மற்றும் சேமிப்பு திட்டங்களுக்கு என்ன வித்தியாசம்?', 'Term plans give pure protection. Savings plans combine protection with a payout. I will explain which suits your goals.', 'டெர்ம் திட்டம் தூய பாதுகாப்பு தரும். சேமிப்பு திட்டம் பாதுகாப்புடன் ஒரு தொகையும் தரும். உங்கள் இலக்கிற்கு எது பொருந்தும் என விளக்குகிறேன்.', 0, true, false, true),
  ('life', 'How do I update my nominee?', 'நாமினியை எப்படி மாற்றுவது?', 'Nominee changes are done through the insurer with a simple form. I can help you with it.', 'காப்பீட்டு நிறுவனத்தில் ஒரு எளிய படிவம் மூலம் நாமினி மாற்றம் செய்யலாம். அதில் உதவுகிறேன்.', 1, true, false, true),
  ('vehicle', 'Can you help renew my vehicle insurance?', 'வாகன காப்பீடு புதுப்பிக்க உதவுவீர்களா?', 'Yes. Send me your current policy on WhatsApp and I will share renewal options.', 'ஆம். உங்கள் தற்போதைய பாலிசியை வாட்ஸ்அப்பில் அனுப்புங்கள், புதுப்பிக்கும் வாய்ப்புகளை பகிர்கிறேன்.', 0, true, true, true),
  ('vehicle', 'What should I do after an accident?', 'விபத்துக்கு பிறகு என்ன செய்ய வேண்டும்?', 'Make sure everyone is safe, take photos and inform the insurer quickly. Call me and I will guide you.', 'அனைவரும் பாதுகாப்பாக இருப்பதை உறுதி செய்து, புகைப்படங்கள் எடுத்து, காப்பீட்டு நிறுவனத்திற்கு விரைவில் தெரிவியுங்கள். என்னை அழையுங்கள், வழிகாட்டுகிறேன்.', 1, true, false, true),
  ('real_estate', 'How do I enquire about a plot?', 'மனை பற்றி எப்படி விசாரிப்பது?', 'Open the listing and call or WhatsApp me. I will share details and arrange a site visit.', 'பட்டியலை திறந்து என்னை அழைக்கவும் அல்லது வாட்ஸ்அப் செய்யவும். விவரங்களை பகிர்ந்து நேரில் பார்வைக்கு ஏற்பாடு செய்கிறேன்.', 0, true, true, true),
  ('real_estate', 'Can you help me sell my property?', 'என் சொத்தை விற்க உதவுவீர்களா?', 'Yes. Share the location, size and expected price and I will tell you the next steps.', 'ஆம். இடம், அளவு மற்றும் எதிர்பார்க்கும் விலையை சொல்லுங்கள், அடுத்த படிகளை சொல்கிறேன்.', 1, true, false, true),
  ('health', 'Can I cover my parents in one plan?', 'என் பெற்றோரை ஒரே திட்டத்தில் சேர்க்கலாமா?', 'Many family plans allow parents to be added. The best option depends on their age and health. Let''s discuss your family''s details.', 'பல குடும்ப திட்டங்களில் பெற்றோரை சேர்க்கலாம். அவர்களின் வயது மற்றும் ஆரோக்கியத்தைப் பொறுத்து சிறந்த வாய்ப்பு மாறும். உங்கள் குடும்ப விவரங்களை பேசுவோம்.', 2, true, false, true),
  ('health', 'What is a waiting period?', 'காத்திருப்பு காலம் என்றால் என்ன?', 'Some illnesses are covered only after a set time from the start of the policy. The exact period depends on the plan.', 'சில நோய்கள் பாலிசி தொடங்கி குறிப்பிட்ட காலத்திற்கு பிறகே உள்ளடங்கும். சரியான காலம் திட்டத்தைப் பொறுத்தது.', 3, true, false, true),
  ('life', 'How much life cover do I need?', 'எனக்கு எவ்வளவு ஆயுள் காப்பீடு தேவை?', 'It depends on your income, loans and family needs. I can help you work out a sensible amount.', 'உங்கள் வருமானம், கடன்கள் மற்றும் குடும்ப தேவைகளைப் பொறுத்தது. சரியான தொகையை கணக்கிட உதவுகிறேன்.', 2, true, false, true),
  ('life', 'Can I pay premiums monthly?', 'மாதந்தோறும் பிரீமியம் செலுத்தலாமா?', 'Many plans offer monthly, quarterly, half-yearly or yearly payment. The options depend on the plan.', 'பல திட்டங்களில் மாதம், காலாண்டு, அரையாண்டு அல்லது ஆண்டு செலுத்தலாம். திட்டத்தைப் பொறுத்தது.', 3, true, false, true),
  ('vehicle', 'My policy has expired. Can I still renew?', 'என் பாலிசி காலாவதியாகிவிட்டது. இன்னும் புதுப்பிக்கலாமா?', 'Usually yes, though a vehicle inspection may be needed. Send me your old policy on WhatsApp and I will check.', 'பொதுவாக முடியும், வாகன ஆய்வு தேவைப்படலாம். பழைய பாலிசியை வாட்ஸ்அப்பில் அனுப்புங்கள், சரிபார்க்கிறேன்.', 2, true, false, true),
  ('vehicle', 'What is a no claim bonus?', 'நோ கிளைம் போனஸ் என்றால் என்ன?', 'A discount on your premium for each claim-free year. It can usually be carried over when you renew.', 'கிளைம் இல்லாத ஒவ்வொரு ஆண்டுக்கும் பிரீமியத்தில் தள்ளுபடி. புதுப்பிக்கும்போது பொதுவாக தொடரலாம்.', 3, true, false, true),
  ('corporate', 'How many employees do I need for a group plan?', 'குழு திட்டத்திற்கு எத்தனை ஊழியர்கள் தேவை?', 'The minimum group size depends on the insurer and plan. Share your team size and I will check the options.', 'குறைந்தபட்ச எண்ணிக்கை நிறுவனம் மற்றும் திட்டத்தைப் பொறுத்தது. உங்கள் குழு அளவை சொல்லுங்கள், சரிபார்க்கிறேன்.', 0, true, false, true),
  ('corporate', 'Can employees add family members?', 'ஊழியர்கள் குடும்பத்தினரை சேர்க்கலாமா?', 'Many group health plans allow spouse, children and sometimes parents. It depends on the plan you choose.', 'பல குழு ஆரோக்கிய திட்டங்களில் துணைவர், குழந்தைகள், சில நேரம் பெற்றோரையும் சேர்க்கலாம். திட்டத்தைப் பொறுத்தது.', 1, true, false, true)
) as v(category, question_en, question_ta, answer_en, answer_ta, sort, published, show_on_home, is_sample)
where not exists (select 1 from public.faqs where is_sample);
